/* V15 canonical architectural overrides. Earlier functions remain only as migration context;
   every exported figure and publication below resolves to these declarations. */
function mapContext(name,x,y,w,h,dark=false,opacity=1){
  const c=CONTEXT.contexts[name],sx=w/1000,sy=h/1000;
  const light={building:['#d4d9d4','#abb6ae',1.5],park:['#d7e7dc','#9fc3aa',1.2],water:[C.water,C.water,2.5],rail:['none','#68756f',4],road_major:['none','#9ca8a1',4],road_local:['none','#bdc5c0',2],path:['none','#d0d7d2',1.5]};
  const night={building:['#28483d','#35594d',1.4],park:['#1d4a39','#2c6b50',1.2],water:['none','#69bbcf',2.5],rail:['none','#c9d3ce',4],road_major:['none','#7f9389',4],road_local:['none','#456257',2],path:['none','#38564b',1.5]};
  const st=dark?night:light;
  const features=c.features.filter((f,i)=>f.kind==='road_local'?i%3===0:f.kind==='path'?i%2===0:true);
  return `<g transform="translate(${x} ${y}) scale(${sx} ${sy})" opacity="${opacity}">${features.map(f=>{const s=st[f.kind]||st.path;const pts=f.points.length>16?f.points.filter((_,i)=>i%2===0):f.points;return (f.kind==='building'||f.kind==='park')?poly(pts,`fill="${s[0]}" stroke="${s[1]}" stroke-width="${s[2]/Math.max(sx,sy)}"`):line(pts,`stroke="${s[1]}" stroke-width="${s[2]/Math.max(sx,sy)}" stroke-linecap="round"`)}).join('')}</g>`;
}
