function pdfCss(a0mode=false){return `@page{size:${a0mode?'1189mm 841mm':'420mm 297mm'};margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;background:${C.paper};font-family:'Segoe UI','Microsoft YaHei',Arial,sans-serif;color:${C.ink}}.page,.board{page-break-after:always;position:relative;overflow:hidden;background:${C.paper}}.page{width:420mm;height:297mm;padding:9mm 11mm 8mm}.board{width:1189mm;height:841mm}.board>svg{width:100%;height:100%}.page header{height:8mm;display:flex;justify-content:space-between;border-bottom:.35mm solid #9aa9a0;font-size:10pt;font-weight:800;letter-spacing:.04em}.page h1{margin:5mm 0 1mm;font-size:24pt;line-height:1.05}.page .sub{margin:0 0 3mm;font-size:11pt;color:${C.graphite};font-weight:700}.page .content{height:244mm;overflow:hidden}.page .content>svg{width:100%;height:100%;display:block}.page footer{position:absolute;left:11mm;right:11mm;bottom:5mm;border-top:.25mm solid #aeb9b2;padding-top:2mm;font-size:8pt;color:${C.graphite};font-weight:700}.page footer i{float:right;font-style:normal}.page:last-child,.board:last-child{page-break-after:auto}`}
async function writePng(source,name){await sharp(Buffer.from(source),{density:190}).resize(2700,1650).png({compressionLevel:9,palette:true,quality:96}).toFile(path.join(FIG,name))}
async function exportPdf(page,lang){const suffix=lang==='en'?'.en':'';for(const [kind,html,a0mode] of [['a3',a3(lang),false],['a0',a0(lang),true]]){await page.setContent(`<html lang="${lang}"><meta charset="utf-8"><style>${pdfCss(a0mode)}</style><body>${html}</body></html>`,{waitUntil:'load'});const final=path.join(DRAW,`${kind==='a3'?'a3-booklet':'a0-boards'}${suffix}.pdf`);await page.pdf({path:final,printBackground:true,preferCSSPageSize:true,scale:a0mode?.98:1,tagged:false,outline:false})}}

async function build(){
  updateContent();
  for(const lang of ['zh','en']){const s=lang==='en'?'.en.png':'.png';await writePng(overall(lang),`site-overview${s}`);await writePng(groundInterface(lang),`land-use-structure${s}`);await writePng(keyAreas(lang),`key-areas${s}`);await writePng(mobility(lang),`mobility-bluegreen${s}`);await writePng(metrics(lang),`metrics-evidence${s}`);await writePng(axon(lang),`hero-s7-assembly${s}`);await writePng(section(lang),`hero-s7-section${s}`);await writePng(s7Plan(lang),`hero-s7-detail${s}`)}
  const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'});const page=await browser.newPage();for(const lang of ['zh','en'])await exportPdf(page,lang);await browser.close();
  console.log('V16 approved-context figures and four vector-first PDFs generated');
}

module.exports={build,overall,groundInterface,keyAreas,mobility,metrics,jury,s7Plan,section,nodeDetail,axon,a3,a0,pdfCss};
if(require.main===module)build().catch(e=>{console.error(e);process.exit(1)});
